  /* ══════════ EXPANSION NORMALISÉE ══════════ */
  function nk(s) { return String(s == null ? "" : s).toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-z0-9]/g, ""); }
  function slug(s) { return nk(s).replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "") || "x"; }
  function num(v, d) { var n = Number(v); return isFinite(n) ? n : d; }
  function txt(v, d) { var s = String(v == null ? "" : v).trim(); return s || d; }

  var brands = [], bSet = {};
  BR.forEach(function (b) {
    if (!b || !b[0] || bSet[b[0]]) return;
    bSet[b[0]] = 1;
    brands.push([txt(b[0], "x"), txt(b[1], b[0]), txt(b[2], "—"), txt(b[3], "—"), txt(b[4], "europe")]);
  });

  var md = {}, models = [];
  brands.forEach(function (b) {
    var bid = b[0], raw = MDP[bid];
    md[bid] = [];
    if (!raw) return;
    String(raw).split("|").forEach(function (r) {
      var f = String(r).split("^");
      var name = txt(f[0], "");
      if (!name) return;
      var y0 = num(f[1], 2017), y1 = num(f[2], 2027);
      if (y0 > y1) { var t = y0; y0 = y1; y1 = t; }
      var seg = num(f[3], 2), ph = num(f[4], 1);
      if (seg < 0 || seg > 13) seg = 2;
      if (ph < 1 || ph > 12) ph = 1;
      var id = bid + "-" + slug(name);
      var dup = md[bid].some(function (m) { return m[0] === name; });
      if (dup) return;
      md[bid].push([name, y0, y1, seg, ph]);
      models.push({ id: id, b: bid, n: name, y: [y0, y1], seg: seg, phase: ph });
    });
  });

  var fams = [];
  FAM.forEach(function (row) {
    var f = String(row).split("|");
    if (f.length < 10) return;
    var code = txt(f[0], "");
    if (!code) return;
    var fuel = txt(f[1], "e");
    if (["e", "d", "h", "p", "b", "g"].indexOf(fuel) < 0) fuel = "e";
    var variants = String(f[4] || "").split(",").map(function (v) {
      var p = String(v).split(":");
      return [num(p[0], 0), num(p[1], 0)];
    }).filter(function (v) { return v[0] > 0 && v[0] <= 3000; });
    if (!variants.length) return;
    var bl = String(f[8] || "").split(";").map(function (x) { return nk(x); }).filter(Boolean);
    var sl = String(f[9] || "").split(";").map(function (x) { return num(x, -1); }).filter(function (x) { return x >= 0 && x <= 13; });
    fams.push({
      code: code, fuel: fuel, disp: num(f[2], 0), label: txt(f[3], code),
      vars: variants, gb: txt(f[5], "BVM"), y0: num(f[6], 2017), y1: num(f[7], 2027),
      brands: bl, segs: sl
    });
  });

  var me = {};
  models.forEach(function (m) {
    var list = [], seen = {};
    fams.forEach(function (F) {
      if (F.brands.indexOf(nk(m.b)) < 0) return;
      if (F.segs.length && F.segs.indexOf(m.seg) < 0) return;
      var a = Math.max(F.y0, m.y[0]), b = Math.min(F.y1, m.y[1]);
      if (a > b) return;
      F.vars.forEach(function (v) {
        var key = F.code + "|" + v[0] + "|" + F.gb;
        if (seen[key]) return;
        seen[key] = 1;
        list.push([F.code, F.code, F.label + " " + v[0], F.fuel, F.disp, v[0], v[1], F.gb, a, b]);
      });
    });
    if (!list.length) {
      var donor = null;
      for (var i = 0; i < fams.length; i++) { if (fams[i].brands.indexOf(nk(m.b)) > -1) { donor = fams[i]; break; } }
      if (donor) {
        var v0 = donor.vars[0];
        list.push([donor.code, donor.code, donor.label + " " + v0[0], donor.fuel, donor.disp, v0[0], v0[1], donor.gb, m.y[0], m.y[1]]);
      } else {
        list.push(["GEN", "GEN", "Motorisation standard 110", "e", 1598, 110, 250, "BVM6", m.y[0], m.y[1]]);
      }
    }
    me[m.id] = list.slice(0, 6);
  });

