    if (!title) return;
    var sev = txt(f[4], "modérée");
    if (["critique", "majeure", "modérée", "mineure", "info"].indexOf(sev) < 0) sev = "modérée";
    var freq = txt(f[5], "moyenne");
    if (["élevée", "moyenne", "faible"].indexOf(freq) < 0) freq = "moyenne";
    var y0 = num(f[6], 2017), y1 = num(f[7], 2027);
    if (y0 > y1) { var t = y0; y0 = y1; y1 = t; }
